/* Public client configuration is generated by sync-flutter-assets.py. */
importScripts('firebase-messaging-config.js');
importScripts('https://www.gstatic.com/firebasejs/13.3.0/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/13.3.0/firebase-messaging-compat.js');
if (self.meetFirebaseConfig?.appId) {
  firebase.initializeApp(self.meetFirebaseConfig);
  firebase.messaging(); // FCM displays generic notification payloads in the background.
}
self.addEventListener('notificationclick', event => {
  event.notification.close();
  const roomId = event.notification.data?.FCM_MSG?.data?.roomId;
  const url = new URL('/', self.location.origin);
  if (roomId) url.searchParams.set('room', roomId);
  event.waitUntil(clients.matchAll({type: 'window', includeUncontrolled: true}).then(windows => {
    const existing = windows.find(w => new URL(w.url).origin === self.location.origin);
    if (existing) { existing.navigate(url.href); return existing.focus(); }
    return clients.openWindow(url.href);
  }));
});
